def ing(k,a,u,n,s): return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def butter(a): return ing('butter',a,'g','unsalted butter','Use the same weight of a block-style dairy-free butter alternative; flavor and salt content differ.')
def flour(a): return ing('flour',a,'g','all-purpose wheat flour','Use the same weight of a gluten-free all-purpose blend intended for sauces; texture may differ. Cornstarch is not a weight-for-weight replacement.')
def milk(a,k='milk'): return ing(k,a,'ml','whole milk','Use the same volume of unsweetened soy milk; flavor and thickening may differ.')
def water(a,k='water'): return ing(k,a,'ml','drinking water','No replacement is needed; increase cooking water only as needed to cover the food.')
def salt(a,k='salt'): return ing(k,a,'g','fine salt','Reduce or omit; exchange other salt by weight rather than spoon size.')
def yolks(a): return ing('yolks',a,'','large pasteurized egg yolks','Use 18 g pasteurized liquid egg yolk per large yolk. There is no identical egg-free replacement.')
def sugar(a): return ing('sugar',a,'g','granulated sugar','Reduce for a less sweet sauce; do not exchange concentrated sweeteners by weight.')
def pepper(): return ing('pepper',.2,'g','ground white pepper','Use the same weight of black pepper for visible specks, or omit.')
def zest(): return ing('zest',2,'g','finely grated lemon zest, yellow part only','Use the same weight of orange zest for a different citrus flavor.')
def add(id,title,category,n,minutes,description,items,steps,notes,refs=()):
 s=original(id);r=copy.deepcopy(s['recipe']);r.update(title=title,description=description,category=category,servings=n,yieldUnit='sauce portions' if category=='Sauces' else 'servings',minutes=minutes,totalMinutes=minutes,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T13:00:00Z',notes=notes+' Missing amounts, portion yields and timings are modern adaptation estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes ingredient quantities, not cooking time or temperature.',source=s['recipe']['source']+' SavorShelf measured adaptation.'+''.join(' Technique reference: '+url for url in refs))
 r['sourceAliases']=[];r.pop('variants',None)
 records[id]={'sourceId':id,'bodySha256':s['bodySha256'],'recipe':r};newids.append(id);return r
def sauce_steps(): return ['Melt {{butter}} in a separate saucepan over low heat. Stir in {{flour}} and cook for 2 minutes without browning.','Take off the heat and gradually whisk in {{milk}} until smooth. Return to medium-low heat and stir until gently bubbling. Simmer for 5 minutes, stirring along the bottom.']
CUSTARD='https://www.bbcgoodfoodme.com/recipes/homemade-custard/'
add('historical-2a2bfa1369f8beb6ac3507e7','Mléčná Omáčka (Lemon Milk Custard Sauce)','Sauces',8,20,'A sweet milk sauce is enriched with egg yolks and scented with lemon zest for a smooth dessert topping.',[milk(500),milk(50,'coldmilk'),sugar(60),yolks(5),flour(10),zest(),salt(.3)],['Whisk {{flour}} with {{coldmilk}} until smooth. Heat {{milk}}, {{sugar}}, {{zest}} and {{salt}} in a heavy saucepan until steaming.','Whisk in the flour slurry and bring to a gentle simmer. Cook for 2 minutes, stirring continuously along the bottom. Remove from the heat.','Whisk {{yolks}} in a heatproof bowl. Gradually whisk in a ladleful of the hot milk mixture, then pour everything back into the pan.','Stir over low heat until the sauce reaches 82°C (180°F) and coats a spoon; do not boil. Pour into a clean jug and serve warm.'],'The source milk, sugar and yolk quantities are retained. Extra cold milk, flour and zest are assigned measured amounts. Flour is cooked before the yolk liaison to avoid an uncooked-flour finish.',[CUSTARD,EGG])
vanilla=ing('flavor',2.5,'ml','vanilla extract','Use 2 g finely grated lemon zest for a citrus version.')
starch=ing('starch',5,'g','cornstarch','Use 5 g potato starch for a slightly different texture; avoid extended boiling.')
r=add('historical-af2f0ccb3ba8c763f9d980d6','Milchsauce (Vanilla Milk and Yolk Sauce)','Sauces',4,20,'A lightly sweetened milk sauce uses a small starch thickener and egg yolks, with vanilla, cocoa and lemon variations.',[milk(250),milk(60,'coldmilk'),sugar(15),salt(.3),starch,yolks(2),vanilla],['Whisk {{starch}} with {{coldmilk}} in a bowl until smooth. Heat {{milk}}, {{sugar}} and {{salt}} in a saucepan until steaming.','Whisk the starch slurry into the hot milk. Bring to a gentle simmer, stirring, and cook for 1 minute. Remove from the heat.','Whisk {{yolks}} in a bowl. Gradually whisk in a ladleful of hot milk mixture, then return everything to the pan.','Stir over low heat until the sauce reaches 82°C (180°F) and lightly coats a spoon, without boiling. Remove from the heat, stir in {{flavor}} and serve warm.'],'The source milk, sugar, starch and yolk amounts are retained. Four tablespoons of extra milk become a modern 60 ml. Vanilla extract replaces unspecified vanilla sugar. The unprocessed bitter-almond option is omitted; cocoa, lemon and the source egg-free thickening ratio are retained as named variations.',[CUSTARD,EGG])
cocoa=ing('flavor',15,'g','unsweetened cocoa powder','Use the vanilla base recipe instead for a non-chocolate sauce.')
r['variants']=[]
for id,label,item in [('cocoa','Cocoa milk sauce',cocoa),('lemon','Lemon milk sauce',dict(zest(),key='flavor'))]:
 steps=copy.deepcopy(r['steps'])
 if id=='cocoa':
  steps[0]='Whisk {{starch}} and {{flavor}} with {{coldmilk}} until smooth. Heat {{milk}}, {{sugar}} and {{salt}} in a saucepan until steaming.'
  steps[-1]=steps[-1].replace(', stir in {{flavor}}','')
 r['variants'].append(dict(id=id,label=label,ingredients=[copy.deepcopy(i) if i['key']!='flavor' else item for i in r['ingredients']],steps=steps))
r['variants'].append(dict(id='egg-free',label='Egg-free vanilla sauce',ingredients=[dict(i,amount=6) if i['key']=='starch' else copy.deepcopy(i) for i in r['ingredients'] if i['key']!='yolks'],steps=[r['steps'][0],r['steps'][1],'Stir in {{flavor}} and serve warm; this version has a lighter, less rich texture.']))
add('historical-aa553e3417f467e5125762b2','Salsa Blanca sin Mantequilla (Oil and Yolk Sauce)','Sauces',6,15,'An uncooked mayonnaise-style sauce emulsifies oil with egg yolks and vinegar, then finishes with a little pepper.',[yolks(2),ing('oil',150,'ml','neutral vegetable oil','Use the same volume of mild olive oil for a stronger flavor.'),ing('vinegar',15,'ml','white wine vinegar','Use the same volume of cider vinegar.'),salt(1),pepper()],['Use pasteurized eggs for this uncooked sauce. Whisk {{yolks}}, {{vinegar}} and {{salt}} in a clean bowl until evenly combined.','Measure {{oil}} into a jug. Whisk it into the yolks a few drops at a time until the mixture begins to thicken, then continue in a very thin stream while whisking constantly.','Mix in {{pepper}}. Serve promptly, or cover and refrigerate at 4°C (40°F) or colder immediately. Prepare only what is needed for the day; this recipe is not shelf-stable.'],'Two yolks are retained, with both whisked in at the start for a simpler emulsion. Oil, vinegar and seasoning amounts are modern choices; 150 ml is not asserted to be an exact conversion of the source ounces. The source pepper option is selected instead of nutmeg.',[EGG])
add('historical-e02b0f72a81d31d493bba0ea','Gewelde Boter (Whipped Butter Sauce)','Sauces',8,10,'Soft butter is beaten with a little lukewarm water into a light, creamy sauce for immediate serving.',[butter(200),water(50),salt(1)],['Let {{butter}} soften until easily beaten, around 20–22°C (68–72°F), without melting it. Beat in a bowl until smooth and light.','Dissolve {{salt}} in {{water}}, warmed only to about 30°C (86°F). Beat the water into the butter one teaspoon at a time, incorporating each addition before adding more.','Stop adding liquid temporarily if the mixture separates; cool the bowl briefly and beat until smooth before continuing. Serve immediately. Do not boil or melt the finished sauce.'],'This is a whipped butter emulsion, not simply melted butter. The source approximate equal-volume water quantity is reduced to 50 ml per 200 g butter, following a documented Dutch 100 g butter to 25 ml water formula. This change is deliberate and disclosed.', ['https://www.dbnl.org/tekst/groo068rece01_01/groo068rece01_01_0012.php'])
add('historical-741e9e16fa61611d0e3c972d','Lamb’s Feet with Lemon and Yolk Sauce','Main dishes',6,270,'Slow-simmered lamb’s feet are deboned and served in their gelatin-rich cooking broth, finished with lemon, butter and egg yolk.',[ing('feet',12,'','butcher-cleaned lamb’s feet, scalded, dehaired and trimmed','Ask a butcher for cleaned lamb or sheep feet. Mature sheep feet may need longer cooking; boneless lamb is not an equivalent replacement.'),water(3000),ing('broth',500,'ml','strained lamb-foot cooking broth, reserved from this recipe','Use the broth produced in the preceding steps; plain water lacks its gelatin and flavor.'),salt(3),pepper(),ing('lemon',30,'ml','lemon juice','Use the same volume of lime juice for a different citrus flavor.'),yolks(1),butter(14)],['Place {{feet}} in a large pot with {{water}}, adding more water only if needed to cover. Bring to a boil, skim off surface foam, then reduce to a gentle simmer.','Cover loosely and simmer for 2–4 hours, or longer if needed, until the skin and connective tissue are very tender and pull easily from the bones. Top up with water to keep submerged.','Lift out the feet and cool only until safe to handle. Remove every bone and piece of hard gristle carefully; cut the edible soft tissue into 2 cm pieces. Strain the cooking liquid through a fine sieve.','Return the deboned meat to a clean pan. Measure {{broth}} from the strained cooking liquid and add it to the meat. Add {{salt}}, {{pepper}} and {{lemon}}, and simmer for 5 minutes.','Whisk {{yolks}} in a bowl. Gradually whisk in several spoonfuls of hot broth, then return to the pan. Stir gently until the sauce reaches 74°C (165°F), without boiling. Remove from the heat and stir in {{butter}}. Serve immediately.'],'The missing cleaning, long simmer, deboning and butter steps are supplied. Cooking time depends strongly on size and age; tenderness is the endpoint. The broth quantity is a modern 500 ml choice. Discard the unused cooking water or cool it promptly for separate use; it is not all part of the sauce.', ['https://taste.co.za/recipes/lamb-trotters/',EGG])
potato=ing('potatoes',450,'g','peeled waxy potatoes, cut into 5 mm slices','Use the same weight of another firm boiling potato; floury potatoes may break apart.')
add('historical-7b625429ab109be7ae379461','Potatoes Finished in White Sauce','Side dishes',4,35,'Thin potato slices finish cooking in a light butter-and-milk sauce, making a soft, creamy side dish.',[potato,water(1000),salt(2,'boilsalt'),salt(1),milk(500),butter(28),flour(14),pepper()],['Bring {{water}} and {{boilsalt}} to a boil. Add {{potatoes}} and simmer for 5 minutes, then drain. The slices will finish cooking in the sauce.']+sauce_steps()+['Add {{salt}} and {{pepper}} to the sauce. Gently fold in the partly cooked potatoes. Simmer over low heat for 10–15 minutes, stirring carefully, until a knife passes easily through a slice. Add a splash of water only if the sauce catches or becomes too thick. Serve hot.'],'The missing white-sauce cross-reference is expanded using a thin milk sauce. Potato and pint quantities are practical modern amounts.',[ROUX])
asparagus=ing('asparagus',500,'g','fresh asparagus, tough lower ends trimmed','Use the same weight of green beans for a different dish; cook until tender, usually 5–7 minutes.')
add('historical-d8027a619a1091584dab1f1f','Cut Asparagus in White Sauce','Side dishes',4,25,'Tender asparagus pieces are folded through a smooth milk sauce for a lightly coated vegetable side.',[asparagus,water(1000),salt(4),milk(250),butter(15),flour(15)],['Cut {{asparagus}} into 2.5 cm pieces. Bring {{water}} and {{salt|0.75}} to a boil. Cook the stem pieces for 2 minutes, add the tips and cook another 1–3 minutes until just tender. Drain well.']+sauce_steps()+['Stir {{salt|0.25}} into the sauce. Fold in the drained asparagus and warm for 1 minute without crushing it. Serve immediately.'],'The source lacks amounts and a sauce formula; both are supplied. Cut-and-coated presentation is retained, distinct from whole spears with sauce served separately.',[ROUX])
add('historical-2e7e500ab29342109640c6c3','Onions in White Sauce','Side dishes',5,35,'Quartered onions are boiled until tender and coated in a milk sauce thickened with butter kneaded with flour.',[ing('onions',5,'','medium onions, about 600 g peeled in total','Use 600 g peeled small onions or shallots; adjust cooking until tender.'),water(1000),milk(480),flour(24),butter(28)],['Peel and quarter {{onions}}. Bring {{water}} to a boil, add the onions and simmer for about 20 minutes until a knife pierces them easily. Drain well.','Mash softened {{butter}} with {{flour}} to make an even paste with no dry flour.','Heat {{milk}} in a saucepan until steaming. Whisk in the butter-flour paste a small piece at a time, then simmer gently for 5 minutes, stirring, until smooth and lightly thickened.','Fold the drained onions into the sauce and warm gently for 2 minutes. Serve hot.'],'The source five onions and kneaded-butter method are retained. Cups and spoonfuls are assigned modern measured amounts; onion size is clarified.')
beans=ing('vegetable',500,'g','green beans, trimmed and cut into 3 cm lengths','Use the cauliflower or chard-stalk named variation for a different vegetable and its cooking time.')
r=add('historical-b6bcfb256f5fadb2a6d47298','Verduras en Salsa Blanca (Vegetables in Milk Sauce)','Side dishes',4,25,'Green beans are cooked separately and coated in a thin milk sauce; cauliflower and chard stalks are retained as named versions.',[beans,water(1000),butter(15),flour(8),milk(250)],['Bring {{water}} to a boil. Add {{vegetable}} and simmer for 5–7 minutes until tender, then drain.']+sauce_steps()+['Fold the cooked vegetables into the sauce and warm for 1 minute. Serve hot.'],'The source permits several vegetables but supplies no amounts. The base selects green beans; separately cooked cauliflower and chard stalks remain complete named variations.',[ROUX])
r['variants']=[]
for id,label,n,name,timing in [('cauliflower','Cauliflower',500,'cauliflower, cut into small florets','6–8'),('chard-stalks','Chard stalks',400,'Swiss chard stalks, trimmed and sliced 1 cm thick','8–12')]:
 items=[ing('vegetable',n,'g',name,'Use another named vegetable version and its stated cooking time.') if i['key']=='vegetable' else copy.deepcopy(i) for i in r['ingredients']]
 r['variants'].append(dict(id=id,label=label,ingredients=items,steps=[r['steps'][0].replace('5–7',timing)]+r['steps'][1:]))
artichokes=ing('artichokes',4,'','medium globe artichokes','Use four large drained canned artichoke hearts for a smaller shortcut dish; warm them separately and omit whole-artichoke preparation and boiling.')
r=add('historical-ab6b4890fba0b53e6d07646e','Alcachofas con Salsa Blanca (Whole Artichokes)','Side dishes',4,60,'Whole globe artichokes are cooked until tender and served with a separate smooth milk sauce for dipping the leaves and heart.',[artichokes,water(2500),butter(25),flour(25),milk(400),salt(2)],['Rinse {{artichokes}}. Trim the stems to about 1 cm, remove the small tough lower leaves and cut about 2 cm off the tops. Snip off sharp leaf tips with kitchen scissors.','Bring {{water}} to a boil in a pot that holds the artichokes comfortably, adding more water if needed to cover. Add the artichokes and simmer, loosely covered, for 30–45 minutes, until a leaf pulls away easily and a knife enters the base without resistance.','Lift out and drain upside down. When cool enough to handle, gently open the centers and scoop out the fuzzy choke with a spoon; do not eat the fuzzy material. Keep the tender bases and leaves intact.']+sauce_steps()+['Stir {{salt}} into the sauce. Serve the warm artichokes with the sauce alongside. Pull off each leaf and scrape the tender flesh at its base with your teeth; discard the tough leaf. Eat the tender heart after the leaves.'],'Two sources share whole cooked artichokes and white sauce. The Mexican source’s brief cooling and reheating presentation is retained as a named variation. The sauce formula and modern cooking cues are supplied.',[ROUX,'https://www.oceanmist.com/recipes/artichoke-bottoms/'])
variant=copy.deepcopy(r['steps']);variant[2]='Lift out the artichokes and briefly cool in a bowl of cool drinking water until safe to handle, retaining the cooking water in the pot. Open the centers and remove the fuzzy choke with a spoon. Return the artichokes to the boiling cooking water for 3–5 minutes until hot, then lift out and drain. This is immediate preparation, not storage at room temperature.'
variant[-1]='Stir {{salt}} into the sauce. Spoon a little into each hot artichoke center and serve the rest alongside. Scrape the tender flesh from the base of each leaf, discarding the tough leaf, and eat the tender heart.'
r['variants']=[dict(id='cooled-reheated',label='Cooled and reheated presentation',ingredients=copy.deepcopy(r['ingredients']),steps=variant)]
old='historical-b789af68b06c3ec21ee9279c';canonical=r['id'];r['sourceAliases']=[old];r['source']+=' Equivalent source retained: '+original(old)['recipe']['source']
aliases[old]=dict(id=old,canonicalId=canonical,bodySha256=original(old)['bodySha256'],reason='Both full sources consist of whole cooked globe artichokes with white sauce. The Mexican cooling/reheating and sauce-in-center presentation remains a named variation; both source credits and saved IDs are preserved.')
cauli=ing('cauliflower',600,'g','cauliflower, trimmed into evenly sized florets','Use the same weight of broccoli florets for a different dish; begin checking tenderness after 4 minutes.')
add('historical-982590fb9339fe34ce1addd1','Coliflor con Salsa Blanca (Cauliflower with Milk Sauce)','Side dishes',4,25,'Tender cauliflower florets are arranged in a mound and covered with a smooth, egg-free white sauce.',[cauli,water(1000),salt(3,'boilsalt'),salt(1),milk(300),butter(20),flour(20)],['Bring {{water}} and {{boilsalt}} to a boil. Add {{cauliflower}} and simmer for 6–8 minutes until tender but still holding its shape. Drain thoroughly.']+sauce_steps()+['Mix {{salt}} into the sauce. Arrange the warm florets in a mound with their tops facing outward and spoon the hot sauce over them. Serve immediately.'],'The source moulded presentation is simplified to an arranged mound. A shorter tenderness-based boil replaces the fixed fifteen minutes. This remains separate from the yolk-enriched cauliflower formula.',[ROUX])
add('historical-1cb4737fed7afe295186ad84','Salsifí con Salsa Blanca (Salsify in White Sauce)','Side dishes',6,45,'Peeled salsify is simmered in an acidulated cooking liquid with beef fat, then drained and coated in a smooth milk sauce.',[ing('salsify',1000,'g','fresh salsify roots','Use the same weight of peeled parsnips for a different flavor; check frequently as cooking time differs.'),water(1000,'soakwater'),water(1500),ing('vinegar',30,'ml','white wine vinegar','Use the same volume of lemon juice for a citrus variation.'),ing('fat',50,'g','rendered beef fat','Use 50 g unsalted butter for a vegetarian, dairy-containing variation.'),salt(10,'boilsalt'),salt(1),milk(400),butter(25),flour(25)],['Mix {{soakwater}} with {{vinegar|0.5}} in a bowl. Scrub and peel {{salsify}}, trim the ends and cut into 7 cm lengths, placing each piece immediately in the acidulated water to limit browning.','Put {{water}}, {{vinegar|0.5}}, {{fat}} and {{boilsalt}} in a saucepan and bring to a gentle simmer. Drain the salsify from its soaking water and add it to the pan.','Simmer until a knife enters easily but the roots still hold their shape, checking after 8 minutes; thick pieces may need 15–25 minutes. Drain and discard the cooking liquid.']+sauce_steps()+['Stir {{salt}} into the sauce. Fold in the hot drained salsify and serve.'],'A practical half-size source batch is used, with extra cooking water as needed to cover. Rendered beef fat replaces raw kidney fat and a tenderness check replaces a rigid half-hour boil. The cooking fat and liquid are largely discarded. Sauce quantities are supplied.',[ROUX,'https://www.greatbritishchefs.com/how-to-cook/how-to-cook-salsify'])
add('historical-9b626e81a4184e1e347aa218','Papas en Salsa Blanca (Potatoes with Tomato and Onion)','Side dishes',4,45,'Boiled potato slices are sautéed with tomato and onion, then lightly bound with a flour-and-water sauce and finished with parsley.',[ing('potatoes',600,'g','whole medium waxy potatoes','Use the same weight of another firm boiling potato; floury potatoes may break apart.'),water(1500),water(150,'saucewater'),salt(4),butter(20),ing('tomato',150,'g','peeled ripe tomato, chopped','Use the same weight of drained canned chopped tomatoes.'),ing('onion',100,'g','peeled onion, finely chopped','Use the same weight of shallots.'),flour(4),ing('parsley',5,'g','fresh parsley, finely chopped','Use 5 g fresh cilantro for a different herbal flavor, or omit.')],['Put {{potatoes}} in a pan with {{water}} and {{salt|0.75}}, adding water only if needed to cover. Bring to a gentle boil and cook for 20–30 minutes until a knife passes through easily. Drain, cool just enough to handle, peel and cut into 1 cm slices.','Melt {{butter}} in a wide pan. Cook {{onion}} over medium-low heat for 5 minutes until soft. Add {{tomato}} and cook for 3 minutes, then add the potato slices and cook gently for another 3 minutes, turning carefully.','Whisk {{flour}} with {{saucewater}} until smooth. Pour into the pan, add {{salt|0.25}} and simmer gently for 5 minutes, stirring carefully, until lightly thickened and the potatoes are hot.','Scatter over {{parsley}} and serve immediately.'],'Despite its name, the source uses tomato, onion and a water slurry rather than a milk-based white sauce. That distinction is retained; missing ingredient amounts and timing are supplied.')
add('historical-fe4916389ef7aa7f66f048f9','Coliflor con Salsa Blanca y Yemas (Cauliflower with Yolk Sauce)','Side dishes',4,30,'Cauliflower florets are covered in a rich white sauce finished with tempered egg yolks.',[cauli,water(1000),salt(3,'boilsalt'),salt(1),milk(300),butter(20),flour(20),yolks(2)],['Bring {{water}} and {{boilsalt}} to a boil. Add {{cauliflower}} and simmer for 6–8 minutes until tender but holding its shape. Drain well and keep warm.']+sauce_steps()+['Remove the sauce from the heat and stir in {{salt}}. Whisk {{yolks}} in a bowl, slowly whisk in several spoonfuls of hot sauce, then return everything to the pan.','Stir over low heat until the sauce reaches 71°C (160°F), without boiling. Arrange the florets in a mound, spoon over the hot sauce and serve immediately.'],'Two yolks are chosen from the source two-or-three range. The missing white-sauce formula is supplied, with a controlled final heating step. This egg-enriched preparation is kept separate from the egg-free cauliflower dish.',[ROUX,EGG])
add('historical-1713096eda29a969b96b3945','Espárragos con Salsa Blanca (Whole Asparagus Spears)','Side dishes',4,25,'Whole asparagus spears are arranged with their tips together and served with warm white sauce in a separate jug.',[asparagus,water(1000),milk(250),butter(15),flour(15),salt(1)],['Bring {{water}} to a gentle boil in a wide pan. Add {{asparagus}} and cook for 4–6 minutes, depending on thickness, until the stems are tender but the tips hold their shape. Lift out and drain well.']+sauce_steps()+['Mix {{salt}} into the sauce. Arrange the warm spears on a platter with the tips aligned toward the center and serve the sauce separately.'],'The missing cooking and sauce cross-references are replaced with complete steps. Whole spears and separate sauce preserve this presentation, distinct from the cut asparagus mixed into sauce.',[ROUX])
